    c0=min(c for r,c in coords); c1=max(c for r,c in coords)
    h=r1-r0+1; w=c1-c0+1
    # Find the most repeated h-by-w patch in the grid; return its values.
    best=None; bestscore=-1
    for r in range(len(grid)-h+1):
      for c in range(len(grid[0])-w+1):
